#!/usr/bin/env bash
# Self-contained CSS для dashboard/bg1-page-round (prod parity ★ BG-1, bash-only).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BOARD="$(cd "$ROUND/../../board-game" && pwd)"
OUT="$ROUND/lab-base.css"
SOURCES=("$BOARD/styles.css" "$BOARD/logic-round/styles.css")

{
  cat <<'HDR'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: dashboard/bg1-page-round */
/* Sources: board-game/styles.css (tokens ADR-014) + board-game/logic-round/styles.css (облегчённые блоки) */

HDR
  for src in "${SOURCES[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

echo "OK: $OUT"
